11	{
12	    template<std::size_t Size>
13	    STOMPTALK_FORCE_INLINE
14	    bool operator()(stomptalk_view name, const char (&text)[Size]) const noexcept
15	    {
16	        assert(name.data || !name.size);
17	        return name.size == Size - 1 && Backend::template equal<Size - 1>(name.data, text);
18	    }
