21	    bool operator()(stomptalk_view name, stomptalk_view expected) const noexcept
22	    {
23	        assert(name.data || !name.size);
24	        assert(expected.data || !expected.size);
25	        return name.size == expected.size && Backend::equal(name.data, expected.data, name.size);
