29	// wire, when non-null, points to 16 readable bytes: LF + name + colon.
30	// Fragmented/decoded names use the plain 14-byte comparison.
31	template<stomptalk_backend Backend>
32	STOMPTALK_FORCE_INLINE
33	bool is_content_length(stomptalk_view name, const char* wire = nullptr) noexcept
34	{
35	    assert(name.data || !name.size);
36	    return name.size == sizeof(backend::content_length_wire) - 3 &&
37	        (wire ? backend::engine<Backend>::is_content_length_wire(wire)
38	              : backend::swar::is_content_length(name.data));
39	}
