16	    static __m128i load(const char* data) noexcept
17	    {
18	        return _mm_loadu_si128(reinterpret_cast<const __m128i*>(data));
19	    }
20	
21	    STOMPTALK_FORCE_INLINE
22	    static unsigned mask(__m128i matches) noexcept
23	    {
24	        return static_cast<unsigned>(_mm_movemask_epi8(matches));
25	    }
26	
27	    STOMPTALK_FORCE_INLINE
28	    static bool equal(const char* data, const char* text, std::size_t size) noexcept
29	    {
30	        while (size >= 16)
31	        {
32	            if (mask(_mm_cmpeq_epi8(load(data), load(text))) != 0xffff)
33	                return false;
34	            data += 16;
35	            text += 16;
36	            size -= 16;
37	        }
38	        return swar::equal(data, text, size);
39	    }
40	
41	    template<std::size_t Size>
42	    STOMPTALK_FORCE_INLINE
43	    static typename std::enable_if<(Size < 16), bool>::type
44	    equal(const char* data, const char* text) noexcept
45	    {
46	        return swar::equal<Size>(data, text);
47	    }
48	
49	    template<std::size_t Size>
50	    STOMPTALK_FORCE_INLINE
51	    static typename std::enable_if<(Size >= 16), bool>::type
52	    equal(const char* data, const char* text) noexcept
53	    {
54	        return mask(_mm_cmpeq_epi8(load(data), load(text))) == 0xffff &&
55	            equal<Size - 16>(data + 16, text + 16);
56	    }
57	
58	    STOMPTALK_FORCE_INLINE
59	    static bool is_content_length_wire(const char* data) noexcept
60	    {
61	        const auto expected = _mm_load_si128(reinterpret_cast<const __m128i*>(content_length_wire));
62	        return mask(_mm_cmpeq_epi8(load(data), expected)) == 0xffff;
63	    }
64	
65	    STOMPTALK_FORCE_INLINE
66	    static const char* scan_header(const char* p, const char* end, bool key, bool literal) noexcept
67	    {
68	        while (end - p >= 16)
69	        {
70	            const auto word = load(p);
71	            auto events = _mm_or_si128(_mm_cmpeq_epi8(word, _mm_setzero_si128()),
72	                _mm_or_si128(_mm_cmpeq_epi8(word, _mm_set1_epi8('\n')),
73	                             _mm_cmpeq_epi8(word, _mm_set1_epi8('\r'))));
74	            if (key || !literal)
75	                events = _mm_or_si128(events, _mm_cmpeq_epi8(word, _mm_set1_epi8(':')));
76	            if (!literal)
77	                events = _mm_or_si128(events, _mm_cmpeq_epi8(word, _mm_set1_epi8('\\')));
78	            const auto found = mask(events);
79	            if (found)
80	                return p + __builtin_ctz(found);
