STOMPTALK_FORCE_INLINE
stomptalk_header_id detect_header(stomptalk_view name) noexcept
{
    assert(name.data || !name.size);

    switch (name.size)
    {
    case headers_2::size:
        return headers_2::find<Backend>(name.data);
    case headers_3::size:
